function findKthNumber(n, k) {
  let current = 1;
  k -= 1;
  while (k > 0) {
    let count = 0;
    let first = current;
    let last = current;
    while (first <= n) {
      count += Math.min(n, last) - first + 1;
      first *= 10;
      last = last * 10 + 9;
    }
    if (count <= k) {
      k -= count;
      current += 1;
    } else {
      k -= 1;
      current *= 10;
    }
  }
  return current;
}

