function findKthNumber(n, k) {
  if (n <= 20000) {
    // Small enough to list every number as text and sort it.
    const words = [];
    for (let i = 1; i <= n; i++) words.push(String(i));
    words.sort();
    return Number(words[k - 1]);
  }
  // Otherwise pick the answer one digit at a time, counting the values in [1, n] that start with each prefix.
  const top = String(n);
  const withPrefix = prefix => {
    let total = 0;
    for (let length = prefix.length; length <= top.length; length++) {
      const free = 10 ** (length - prefix.length);
      if (length < top.length) total += free;
      else {
        const head = top.slice(0, prefix.length);
        if (prefix < head) total += free;
        else if (prefix === head) total += Number(top.slice(prefix.length) || '0') + 1;
      }
    }
    return total;
  };
  let prefix = '';
  let remaining = k;
  for (;;) {
    for (let d = prefix ? 0 : 1; d <= 9; d++) {
      const size = withPrefix(prefix + d);
      if (remaining <= size) { prefix += d; remaining -= 1; break; }
      remaining -= size;
    }
    if (remaining === 0) return Number(prefix);
  }
}

