function generate(rand, size) {
  const pickK = n => 1 + Math.floor(rand() * n);
  if (size === 'large') {
    const n = 1 + Math.floor(rand() * 1e9);
    return [n, pickK(n)];
  }
  const pick = rand();
  let n;
  if (pick < 0.3) n = 1 + Math.floor(rand() * 30);
  else if (pick < 0.55) {
    // Near a power of ten, where a new level of the tree opens up.
    const power = 10 ** (1 + Math.floor(rand() * 4));
    n = Math.max(1, power + Math.floor(rand() * 7) - 3);
  } else if (pick < 0.85) n = 1 + Math.floor(rand() * 2000);
  else n = 1 + Math.floor(rand() * 1e9);
  const r = rand();
  const k = r < 0.1 ? 1 : r < 0.2 ? n : pickK(n);
  return [n, k];
}
